mapper.select:
SELECT o.order_id, o.order_no, o.user_id, u.user_name, o.order_amount, o.payment_amount, DATE_FORMAT(o.payment_time, '%Y-%m-%d %H:%i:%s') as payment_time, DATE_FORMAT(o.delivery_time, '%Y-%m-%d %H:%i:%s') as delivery_time, o.shipping_fee, o.discount_amount, o.points_deduction, o.shipping_channel, o.tracking_number, o.order_status, DATE_FORMAT(o.create_time, '%Y-%m-%d %H:%i:%s') as create_time FROM shop_order o LEFT JOIN shop_user u ON o.user_id = u.user_id
AND o.user_id = #{userId}
AND o.order_no = #{orderNo}
order_status IN
#{orderStatus}
ORDER BY o.create_time DESC
